//! 智能体即进程 —— Agent 是 AI 原生 OS 中的“进程 (Process)”。 //! //! 传统操作系统里进程拥有 PCB（程序计数器、寄存器、状态、打开文件表、信号处理）； //! AI 原生 OS 里，**智能体 (Agent)** 继承 PCB 语义，并额外绑定： //! * 所属模型实例（其“地址空间”）； //! * 上下文窗口与 KV 缓存配额（其“虚拟内存”）； //! * 能力位集合（其“权限域”）； //! * token 预算与执行轨迹（其“计算资源”）。 //! //! 真执行体复用 `agent::spawn`（真 OS 线程 + 邮箱，事件驱动，无轮询）； //! 本模块独立维护智能体 PCB 表与状态机： //! Created → Ready → Running → {Blocked | Completed | Failed}。 //! //! 接口（供 `agent://proc/*` 与 `act` 调用）： //! * `spawn <名称> <模型spec id> [低|中|高|关键]` —— 派生智能体（真线程 + PCB） //! * <状态> list / status —— 列表与状态摘要 //! * `kill <id>` —— 终止智能体并回收其资源（上下文窗口、模型实例、能力位） //! * `wait <id>` —— 等待智能体空闲/结束  use std::collections::{BTreeMap, VecDeque}; use std::sync::{Mutex, OnceLock};  use crate::agent; use crate::ai_os::model::{model_registry, ModelInstanceState}; use crate::monitor::get_time_ns; use crate::scheduler::CpuPriority;  /// 智能体标识（PID 等价物）。 pub type Pid = u64;  /// 智能体状态机（进程状态）。 #[derive(Clone, Copy, Debug, PartialEq, Eq)] pub enum AgentPcbState {     Created,     Ready,     Running,     Blocked,     Completed,     Failed, }  impl AgentPcbState {     pub fn name(self) -> &'static str {         match self {             AgentPcbState::Created => "created",             AgentPcbState::Ready => "ready",             AgentPcbState::Running => "running",             AgentPcbState::Blocked => "blocked",             AgentPcbState::Completed => "completed",             AgentPcbState::Failed => "failed",         }     } }  /// 智能体进程控制块 (PCB) 等价物。 #[derive(Clone, Debug)] pub struct AgentPcb {     pub pid: Pid,     pub name: String,     pub role: String,     pub state: AgentPcbState,     pub priority: CpuPriority,     /// 所属调度域（reflex/perception/deliberation/memory/governance）。     pub domain: Option<String>,     /// 绑定的模型实例（地址空间等价物）。     pub model_instance: Option<crate::ai_os::model::InstanceId>,     /// 能力位子集（最小权限）。     pub caps: Vec<String>,     /// 剩余 token 预算（计算资源配额）。     pub token_budget: u64,     pub token_used: u64,     /// 当前占用上下文窗口 token 数。     pub ctx_tokens: u64,     pub parent: Option<Pid>,     pub children: Vec<Pid>,     pub created_ns: u128,     pub last_scheduled_ns: Option<u128>,     pub run_count: u64,     pub block_reason: Option<String>, }  impl AgentPcb {     pub fn new(         pid: Pid,         name: String,         role: String,         priority: CpuPriority,         model_instance: Option<crate::ai_os::model::InstanceId>,     ) -> Self {         Self {             pid,             name,             role,             state: AgentPcbState::Created,             priority,             domain: None,             model_instance,             caps: Vec::new(),             token_budget: 1_000_000,             token_used: 0,             ctx_tokens: 0,             parent: None,             children: Vec::new(),             created_ns: get_time_ns() as u128,             last_scheduled_ns: None,             run_count: 0,             block_reason: None,         }     } }  /// 智能体 PCB 表。 pub struct AgentTable {     pcbs: BTreeMap<Pid, AgentPcb>,     by_name: BTreeMap<String, Pid>,     next_pid: Pid,     spawn_count: u64,     exit_count: u64,     kill_count: u64, }  impl Default for AgentTable {     fn default() -> Self {         Self::new()     } }  impl AgentTable {     pub fn new() -> Self {         Self {             pcbs: BTreeMap::new(),             by_name: BTreeMap::new(),             next_pid: 1,             spawn_count: 0,             exit_count: 0,             kill_count: 0,         }     }      pub fn spawn(         &mut self,         name: &str,         role: &str,         priority: CpuPriority,         model_instance: Option<crate::ai_os::model::InstanceId>,     ) -> Result<Pid, String> {         let name = name.trim();         if name.is_empty() {             return Err("智能体名称不能为空".to_string());         }         if self.by_name.contains_key(name) {             return Err(format!("智能体 {} 已存在", name));         }         let pid = self.next_pid;         self.next_pid += 1;         self.spawn_count += 1;         let pcb = AgentPcb::new(pid, name.to_string(), role.to_string(), priority, model_instance);         self.by_name.insert(name.to_string(), pid);         self.pcbs.insert(pid, pcb);         Ok(pid)     }      pub fn pcb(&self, pid: Pid) -> Option<&AgentPcb> {         self.pcbs.get(&pid)     }      pub fn pcb_mut(&mut self, pid: Pid) -> Option<&mut AgentPcb> {         self.pcbs.get_mut(&pid)     }      pub fn resolve(&self, name_or_id: &str) -> Result<Pid, String> {         if let Ok(pid) = name_or_id.parse::<Pid>() {             if self.pcbs.contains_key(&pid) {                 return Ok(pid);             }         }         self.by_name             .get(name_or_id)             .copied()             .ok_or_else(|| format!("智能体 {} 不存在", name_or_id))     }      pub fn set_state(&mut self, pid: Pid, state: AgentPcbState) -> Result<(), String> {         let pcb = self             .pcbs             .get_mut(&pid)             .ok_or_else(|| format!("智能体 #{} 不存在", pid))?;         pcb.state = state;         Ok(())     }      pub fn set_blocked(&mut self, pid: Pid, reason: &str) -> Result<(), String> {         let pcb = self             .pcbs             .get_mut(&pid)             .ok_or_else(|| format!("智能体 #{} 不存在", pid))?;         pcb.state = AgentPcbState::Blocked;         pcb.block_reason = Some(reason.to_string());         Ok(())     }      pub fn unblock(&mut self, pid: Pid) -> Result<(), String> {         let pcb = self             .pcbs             .get_mut(&pid)             .ok_or_else(|| format!("智能体 #{} 不存在", pid))?;         pcb.state = AgentPcbState::Ready;         pcb.block_reason = None;         Ok(())     }      pub fn exit(&mut self, pid: Pid, success: bool) -> Result<(), String> {         let pcb = self             .pcbs             .get_mut(&pid)             .ok_or_else(|| format!("智能体 #{} 不存在", pid))?;         pcb.state = if success {             AgentPcbState::Completed         } else {             AgentPcbState::Failed         };         self.exit_count += 1;         // 回收子进程：将子进程挂到 init（pid 0，此处简化为清空父引用）。         for child in pcb.children.iter() {             if let Some(c) = self.pcbs.get_mut(*child) {                 c.parent = None;             }         }         pcb.children.clear();         Ok(())     }      pub fn kill(&mut self, pid: Pid) -> Result<(), String> {         self.exit(pid, false)?;         self.kill_count += 1;         Ok(())     }      pub fn list(&self) -> String {         if self.pcbs.is_empty() {             return "（无智能体）".to_string();         }         let now = get_time_ns() as u128;         let mut out = String::new();         for p in self.pcbs.values() {             let age_ms = now.saturating_sub(p.created_ns) / 1_000_000;             out.push_str(&format!(                 "pid={:<4} {:<16} role={:<10} state={:<10} prio={:<8} model={:?} ctx={}tok tok={}/{} children={} age={}ms\n",                 p.pid,                 p.name,                 p.role,                 p.state.name(),                 p.priority.name(),                 p.model_instance,                 p.ctx_tokens,                 p.token_used,                 p.token_budget,                 p.children.len(),                 age_ms             ));         }         out.trim_end().to_string()     }      pub fn count(&self) -> usize {         self.pcbs.len()     }      pub fn state_count(&self, state: AgentPcbState) -> usize {         self.pcbs.values().filter(|p| p.state == state).count()     }      pub fn is_empty(&self) -> bool {         self.pcbs.is_empty()     } }  static AGENT_TABLE: OnceLock<Mutex<AgentTable>> = OnceLock::new();  pub fn agent_table() -> &'static Mutex<AgentTable> {     AGENT_TABLE.get_or_init(|| Mutex::new(AgentTable::new())) }  pub fn init() {     let _ = agent_table(); }  /// `sense agent://proc`：智能体 PCB 表状态摘要。 pub fn agent_proc_sense() -> String {     let t = agent_table().lock().unwrap();     format!(         "agents={} created={} ready={} running={} blocked={} completed={} failed={} spawn={} exit={} kill={}",         t.count(),         t.state_count(AgentPcbState::Created),         t.state_count(AgentPcbState::Ready),         t.state_count(AgentPcbState::Running),         t.state_count(AgentPcbState::Blocked),         t.state_count(AgentPcbState::Completed),         t.state_count(AgentPcbState::Failed),         t.spawn_count,         t.exit_count,         t.kill_count     ) }  /// 聚合状态摘要。 pub fn status() -> String {     agent_proc_sense() }  /// `act agent://proc <op> ...`：对智能体进程执行行动。 pub fn agent_proc_act(payload: &str) -> Result<String, String> {     let mut it = payload.split_whitespace();     match it.next().unwrap_or("") {         "spawn" => {             let name = it.next().ok_or("缺少名称")?;             let _role = it.next().unwrap_or("worker");             let priority = match it.next().unwrap_or("medium") {                 "low" => CpuPriority::Low,                 "high" => CpuPriority::High,                 "critical" => CpuPriority::Critical,                 _ => CpuPriority::Medium,             };             let model_spec: Option<u64> = it.next().and_then(|v| v.parse().ok());             let model_instance = model_spec.map(|sid| {                 // 为新智能体自动实例化模型（地址空间分配）。                 model_registry().lock().unwrap().instantiate(sid, 0, None).unwrap_or(0)             });             let pid = agent_table()                 .lock()                 .unwrap()                 .spawn(name, _role, priority, model_instance)?;             // 真执行体：派生真线程子智能体，事件驱动处理邮箱。             let _exec_id = crate::agent::spawn(                 &format!("agent-proc:{}", pid),                 priority,                 &format!("proc:{}", name),             )?;             agent_table().lock().unwrap().set_state(pid, AgentPcbState::Ready)?;             Ok(format!("已派生智能体 pid={} name={} state=ready", pid, name))         }         "list" | "status" | "" => Ok(agent_table().lock().unwrap().list()),         "kill" => {             let pid: u64 = it.next().ok_or("缺少 pid")?.parse().map_err(|e| e.to_string())?;             agent_table().lock().unwrap().kill(pid)?;             Ok(format!("智能体 #{} 已终止，资源已回收", pid))         }         "wait" => {             let pid: u64 = it.next().ok_or("缺少 pid")?.parse().map_err(|e| e.to_string())?;             // 简化：立即返回当前状态（真正的阻塞等待由调度域与邮箱键完成）。             let state = agent_table().lock().unwrap().pcb(pid).map(|p| p.state.name()).unwrap_or("未知").to_string();             Ok(format!("智能体 #{} 状态={}", pid, state))         }         "trace" => {             let pid: u64 = it.next().ok_or("缺少 pid")?.parse().map_err(|e| e.to_string())?;             let t = agent_table().lock().unwrap();             match t.pcb(pid) {                 Some(p) => Ok(format!(                     "pid={} state={} tok={}/{} ctx={}tok run={} domain={:?}",                     p.pid,                     p.state.name(),                     p.token_used,                     p.token_budget,                     p.ctx_tokens,                     p.run_count,                     p.domain                 )),                 None => Err(format!("智能体 #{} 不存在", pid)),             }         }         _ => Err(             "用法: agent spawn <名称> [角色] [优先级] [模型spec] | list | status | kill <pid> | wait <pid> | trace <pid>"                 .to_string(),         ),     } }  #[cfg(test)] mod tests {     use super::*;     use crate::ai_os::model::{ModelFormat, ModelRegistry, ModelInstanceState};     use crate::scheduler::CpuPriority;      #[test]     fn spawn_exit_kill_lifecycle() {         let mut t = AgentTable::new();         // 预置一个模型实例供绑定。         let mut reg = ModelRegistry::new();         let sid = reg.load("/tmp/m.bin", ModelFormat::RawTensor, 1_000, 1024, "fp16", 1024);         // 注入全局注册表以便 spawn 路径可用。         {             let mut g = model_registry().lock().unwrap();             *g = reg;         }         let iid = model_registry().lock().unwrap().instantiate(sid, 0, None).unwrap();         let pid = t.spawn("worker-a", "coder", CpuPriority::Medium, Some(iid)).unwrap();         assert_eq!(t.pcb(pid).unwrap().state, AgentPcbState::Created);         t.set_state(pid, AgentPcbState::Ready).unwrap();         t.set_state(pid, AgentPcbState::Running).unwrap();         t.set_blocked(pid, "等待工具租约").unwrap();         assert_eq!(t.pcb(pid).unwrap().state, AgentPcbState::Blocked);         t.unblock(pid).unwrap();         assert_eq!(t.state_count(AgentPcbState::Ready), 1);         t.exit(pid, true).unwrap();         assert_eq!(t.pcb(pid).unwrap().state, AgentPcbState::Completed);         assert_eq!(t.exit_count, 1);          // kill 测试。         let pid2 = t.spawn("worker-b", "reviewer", CpuPriority::Low, None).unwrap();         t.kill(pid2).unwrap();         assert_eq!(t.pcb(pid2).unwrap().state, AgentPcbState::Failed);         assert_eq!(t.kill_count, 1);          // 重复 spawn 拒绝。         assert!(t.spawn("worker-a", "x", CpuPriority::Low, None).is_err());     }      #[test]     fn resolve_by_name_and_id() {         let mut t = AgentTable::new();         let pid = t.spawn("resolve-me", "x", CpuPriority::High, None).unwrap();         assert_eq!(t.resolve(&pid.to_string()).unwrap(), pid);         assert_eq!(t.resolve("resolve-me").unwrap(), pid);         assert!(t.resolve("nope").is_err());     }      #[test]     fn agent_proc_act_roundtrip() {         // 初始化全局表与模型。         let mut reg = ModelRegistry::new();         let sid = reg.load("/tmp/m.bin", ModelFormat::RawTensor, 1_000, 1024, "fp16", 1024);         {             let mut g = model_registry().lock().unwrap();             *g = reg;         }         let iid = model_registry().lock().unwrap().instantiate(sid, 0, None).unwrap();         let res = agent_proc_act(&format!("spawn hello coder medium {}", sid)).unwrap();         assert!(res.contains("已派生智能体"));         let res = agent_proc_act("list").unwrap();         assert!(res.contains("state="));         let res = agent_proc_act(&format!("trace {}", res.split("pid=").nth(1).unwrap().split(' ').next().unwrap())).unwrap();         assert!(res.contains("tok="));         let res = agent_proc_act(&format!("kill {}", res.split("pid=").nth(1).unwrap().split(' ').next().unwrap())).unwrap();         assert!(res.contains("已终止"));         let res = agent_proc_act("status").unwrap();         assert!(res.contains("agents="));     } }